import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

public class T {
    public static void main(String[] args) {
        Document doc = Jsoup.parse("<article id=a><h1></h1><h2></h2><p><b></b><i></i></p></article><article id=z><h1></h1><p></p><b></b><i></i></article>");
        String[] qs = {
            "article:h\\61 s(> h1 + h2)",
            "article:h\\61 s(> b + i)",
            "article:h\\61 s(p:h\\61 s(> b + i))",
            "article:h\\61 s(:sc\\6f pe > p > b + i)",
            "article:h\\61 s(+ article)",
            "article:has(> h1 + h2)",
            "article:has(:scope > p > b + i)",
        };
        for (String q : qs) {
            try {
                StringBuilder sb = new StringBuilder();
                for (Element el : doc.select(q)) sb.append(el.id()).append(' ');
                System.out.println(q + "  =>  " + sb);
            } catch (Exception e) {
                System.out.println(q + "  =>  ERROR: " + e);
            }
        }
    }
}
