/* Test if a :has branch is anchored to the scope root via a leading + or ~ combinator (and so should be evaluated
   against the scope's following siblings, vs its descendants). */
private static boolean evalWantsSiblings(Evaluator eval) {
    if (eval instanceof PreviousSibling || eval instanceof ImmediatePreviousSibling)
        return reachesScopeRoot(((StructuralEvaluator) eval).evaluator);
    if (eval instanceof CombiningEvaluator) {
        for (Evaluator inner : ((CombiningEvaluator) eval).evaluators)
            if (evalWantsSiblings(inner)) return true;
        return false;
    }
    if (eval instanceof ImmediateParentRun) {
        for (Evaluator inner : ((ImmediateParentRun) eval).evaluators)
            if (evalWantsSiblings(inner)) return true;
        return false;
    }
    if (eval instanceof Has)
        return false; // a nested :has re-anchors to its own scope element
    if (eval instanceof StructuralEvaluator)
        return evalWantsSiblings(((StructuralEvaluator) eval).evaluator);
    return false;
}

/* Test if the evaluator chain reaches the scope root anchor (a leading combinator's Root, or an explicit :scope). */
private static boolean reachesScopeRoot(Evaluator eval) {
    if (eval instanceof Root || eval instanceof Scope) return true;
    if (eval instanceof CombiningEvaluator) {
