import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

public class T3 {
    static void q(Document doc, String query) {
        try {
            StringBuilder sb = new StringBuilder();
            for (Element el : doc.select(query)) sb.append(el.id().isEmpty()? el.normalName() : el.id()).append(' ');
            System.out.println("[" + query + "]  =>  " + sb);
        } catch (Exception e) {
            System.out.println("[" + query + "]  =>  ERROR: " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        Document doc = Jsoup.parse("<article id=a><h1></h1><h2></h2><p><b></b><i></i></p></article><article id=z><h1></h1><p></p><b></b><i></i></article>");
        q(doc, "article:has(:is(> h1 + h2))");          // a
        q(doc, "article:is(:has(> h1 + h2))");          // a
        q(doc, "article:not(:has(> h1 + h2))");         // z
        q(doc, "article:has(p:not(:has(b)))");          // z (p without b)
        q(doc, "article:has(:is(> h1, > h2))");         // a z
        q(doc, "article:has(> h1 ~ h2)");               // a (child then later sibling, both descendants)
        q(doc, ":scope");                                // document root context
        q(doc, ":scope > html");                         // html
        Element a = doc.selectFirst("#a");
        System.out.println("a.select(\":scope > h1 + h2\") => " + a.select(":scope > h1 + h2").size()); // 1
        System.out.println("a.select(\"> h1 + h2\") => " + a.select("> h1 + h2").size());               // 1
        // toString round trip
        System.out.println(org.jsoup.select.QueryParser.parse("article:has(:scope > p > b + i)"));
    }
}
